CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES workspaces(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,reset_at timestamptz NOT NULL);
CREATE TABLE clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,industry text NOT NULL,website text NOT NULL DEFAULT '',geography text NOT NULL,currency text NOT NULL DEFAULT 'USD',audience text NOT NULL DEFAULT '',simulated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,name text NOT NULL,price numeric(14,4) NOT NULL CHECK(price>0),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,description text NOT NULL,FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE financial_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,inputs jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,client_id),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE competitors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,name text NOT NULL,website text NOT NULL,kind text NOT NULL DEFAULT 'direct',notes text NOT NULL DEFAULT '',simulated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE creatives(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,name text NOT NULL,storage_key text NOT NULL,mime_type text NOT NULL,size integer NOT NULL,sha256 text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','complete','failed')),error text,simulated boolean NOT NULL DEFAULT false,manual_transcript text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),UNIQUE(workspace_id,client_id,id),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE creative_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,creative_id uuid NOT NULL,parent_id uuid,name text NOT NULL,variable text NOT NULL,instruction text NOT NULL,hypothesis text NOT NULL,status text NOT NULL DEFAULT 'proposed',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),UNIQUE(workspace_id,client_id,id),FOREIGN KEY(workspace_id,client_id,creative_id) REFERENCES creatives(workspace_id,client_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,parent_id) REFERENCES creative_versions(workspace_id,id));
CREATE TABLE analyses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,creative_id uuid NOT NULL,result jsonb NOT NULL,cache_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,creative_id),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,client_id,creative_id) REFERENCES creatives(workspace_id,client_id,id) ON DELETE CASCADE);
CREATE TABLE forecasts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,analysis_id uuid,assumptions jsonb NOT NULL,result jsonb NOT NULL,provenance text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,analysis_id) REFERENCES analyses(workspace_id,id));
CREATE TABLE recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,analysis_id uuid NOT NULL,label text NOT NULL,reasoning jsonb NOT NULL,FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id),FOREIGN KEY(workspace_id,analysis_id) REFERENCES analyses(workspace_id,id));
CREATE TABLE research_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,title text NOT NULL,url text NOT NULL,excerpt text NOT NULL,kind text NOT NULL,provenance text NOT NULL CHECK(provenance IN ('observed','estimated','simulated')),fetched_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',UNIQUE(workspace_id,client_id,url),FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE market_opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,analysis_id uuid NOT NULL,data jsonb NOT NULL,FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id),FOREIGN KEY(workspace_id,analysis_id) REFERENCES analyses(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE trends(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,analysis_id uuid NOT NULL,data jsonb NOT NULL,FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id),FOREIGN KEY(workspace_id,analysis_id) REFERENCES analyses(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE experiments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,creative_id uuid NOT NULL,variant_id uuid,name text NOT NULL,proposal jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','running','completed','stopped')),results jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,client_id,creative_id) REFERENCES creatives(workspace_id,client_id,id),FOREIGN KEY(workspace_id,client_id,variant_id) REFERENCES creative_versions(workspace_id,client_id,id));
CREATE TABLE knowledge_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,client_id uuid NOT NULL,industry text NOT NULL,sample_size integer NOT NULL CHECK(sample_size>=0),period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,confidence text NOT NULL,finding jsonb NOT NULL,FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id));
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,creative_id uuid NOT NULL,kind text NOT NULL DEFAULT 'analyze',status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,lock_token uuid,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,creative_id,kind),FOREIGN KEY(workspace_id,creative_id) REFERENCES creatives(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE provider_cache(key text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),value jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid REFERENCES users(id),action text NOT NULL,entity_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON jobs(status,available_at);
CREATE INDEX creative_client ON creatives(workspace_id,client_id,created_at DESC);
CREATE INDEX audit_workspace ON audit_logs(workspace_id,created_at DESC);
CREATE INDEX research_client ON research_sources(workspace_id,client_id);
